// Social networks (Facebook, Viber, LinkedIn) need 1200×630 JPG/PNG previews, not WebP.
// The JPGs are generated by scripts/generate-og-images.mjs from og-sources.json.
import ogSources from "./og-sources.json";

export const OG_IMAGE_SOURCES: readonly string[] = ogSources;

export const OG_IMAGE_SIZE = { width: 1200, height: 630 } as const;

export function ogImagePath(source: string) {
  const name = source.split("/").pop()!.replace(/\.webp$/, "");
  return `/images/og/${name}.jpg`;
}

export const DEFAULT_OG_IMAGE = ogImagePath(OG_IMAGE_SOURCES[0]);

export function toOgImage(source?: string) {
  if (source && OG_IMAGE_SOURCES.includes(source)) {
    return ogImagePath(source);
  }
  return DEFAULT_OG_IMAGE;
}
